import { cookies } from "next/headers";

const API = "http://localhost:8000";

export async function getFullMedia(type: string, id: string) {
  const cookieStore = await cookies();

  const cookieHeader = cookieStore
    .getAll()
    .map((c) => `${c.name}=${c.value}`)
    .join("; ");

  const res = await fetch(`${API}/full/${type}/${id}`, {
    headers: {
      Cookie: cookieHeader, // 🔥 manually forward cookies
    },
    cache: "no-store",
  });

  if (!res.ok) {
    const text = await res.text();
    console.error("FULL MEDIA ERROR:", res.status, text);
    throw new Error("Failed to fetch full media");
  }

  return res.json();
}
