import { getFullMedia } from "@/lib/server-api";
import AddToWatchPopButton from "@/components/AddToWatchpopButton";
import MovieDetails from "@/components/MovieDetails";
import MusicDetails from "@/components/MusicDetails";

export default async function MediaPage({
  params,
}: {
  params: Promise<{ type: string; id: string }>;
}) {
  const { type, id } = await params;
  const media = await getFullMedia(type, id);

  return (
    <div className="relative max-w-6xl mx-auto px-6 py-16 text-zinc-100">
      {/* Background Blur */}
      {media.poster && (
        <div
          className="absolute inset-0 -z-10 bg-cover bg-center blur-3xl opacity-15"
          style={{ backgroundImage: `url(${media.poster})` }}
        />
      )}

      {/* HERO */}
      <section className="flex flex-col md:flex-row gap-12 items-start">
        {/* Poster */}
        {media.poster && (
          <img
            src={media.poster}
            alt={media.title}
            className="w-64 rounded-2xl shadow-2xl object-cover"
          />
        )}

        {/* Title + Meta */}
        <div className="flex-1">
          <h1 className="text-4xl md:text-5xl font-semibold tracking-tight">
            {media.title}
          </h1>

          {media.subtitle && (
            <p className="mt-3 text-zinc-400 text-lg">{media.subtitle}</p>
          )}

          <div className="mt-5 flex flex-wrap gap-4 text-sm text-zinc-400">
            {media.genre && <span>{media.genre}</span>}
            {media.release_date && <span>{media.release_date}</span>}
          </div>

          {/* Action Row */}
          <div className="mt-8">
            <AddToWatchPop
              item={{ id, title: media.title }}
              type={type as "movie" | "music"}
            />
          </div>
        </div>
      </section>

      {/* OVERVIEW */}
      {media.description && (
        <section className="mt-20 max-w-3xl">
          <div className="border-t border-zinc-800 pt-10">
            <p className="text-xs tracking-widest text-zinc-500 uppercase mb-6">
              Overview
            </p>

            <p className="text-zinc-400 leading-relaxed">
              {media.description.substring(media.description)}
            </p>
          </div>
        </section>
      )}

      {/* USER TAGS */}
      {media.tags?.length > 0 && (
        <section className="mt-12">
          <h2 className="text-xl font-semibold mb-4">Your Tags</h2>
          <div className="flex gap-3 flex-wrap">
            {media.tags.map((tag: string) => (
              <span
                key={tag}
                className="px-3 py-1 bg-zinc-800 rounded-full text-xs"
              >
                #{tag}
              </span>
            ))}
          </div>
        </section>
      )}

      {/* TYPE-SPECIFIC DETAILS */}
      <section className="mt-16 space-y-12">
        {type === "movie" && <MovieDetails data={media.provider_data} />}
        {type === "music" && <MusicDetails data={media.provider_data} />}
      </section>
    </div>
  );
}
