import { Detail } from "./Detail";
import { Section } from "./Section";

export default function MovieDetails({ data }: any) {
  return (
    <div className="space-y-6">
      <Section title="Cast & Crew">
        <Detail label="Director" value={data.Director} />
        <Detail label="Writer" value={data.Writer} />
        <Detail label="Actors" value={data.Actors} />
      </Section>

      <Section title="Ratings">
        <Detail label="IMDb" value={data.imdbRating} />
        <Detail label="Metascore" value={data.Metascore} />
        <Detail label="Votes" value={data.imdbVotes} />
      </Section>

      <Section title="Technical Info">
        <Detail label="Runtime" value={data.Runtime} />
        <Detail label="Language" value={data.Language} />
        <Detail label="Country" value={data.Country} />
        <Detail label="Box Office" value={data.BoxOffice} />
        <Detail label="Awards" value={data.Awards} />
      </Section>
    </div>
  );
}
